// Cross-check the JS port against fixtures generated by the Python package.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { byzantine, formatDefault } from "../src/bdate.js";

const cases = JSON.parse(readFileSync(new URL("../../fixtures/cases.json", import.meta.url), "utf8"));

/** Minutes east of UTC from an ISO string's trailing ±HH:MM. */
function offsetOf(iso) {
  const m = iso.match(/([+-])(\d\d):(\d\d)$/);
  return (m[1] === "-" ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
}

for (const { input, expected, formatted } of cases) {
  test(`${input.date} @ ${input.lat},${input.lon}`, () => {
    const b = byzantine(new Date(input.date), {
      lat: input.lat,
      lon: input.lon,
      withHours: input.with_hours,
      tzOffset: offsetOf(input.date),
    });
    assert.deepEqual(b, expected);
    assert.equal(formatDefault(b), formatted);
  });
}
